function validate([instructions]) {
  if (instructions.length < 1 || instructions.length > 1e5) return 'instructions needs 1 to 10^5 values.';
  if (instructions.some(v => !Number.isInteger(v) || v < 1 || v > 1e5)) return 'Each value is a whole number from 1 to 10^5.';
