function createSortedArray(instructions) {
  const MOD = 1000000007;
  const maxValue = instructions.reduce((a, b) => Math.max(a, b), 0);
  const tree = new Array(maxValue + 1).fill(0);

  function add(value) {
    for (let i = value; i <= maxValue; i += i & -i) {
      tree[i]++;
    }
  }

  function countUpTo(value) {
    let total = 0;
    for (let i = value; i > 0; i -= i & -i) {
      total += tree[i];
    }
    return total;
  }

  let cost = 0;
  for (let inserted = 0; inserted < instructions.length; inserted++) {
    const value = instructions[inserted];
    const smaller = countUpTo(value - 1);
    const larger = inserted - countUpTo(value);
    cost = (cost + Math.min(smaller, larger)) % MOD;
    add(value);
  }
  return cost;
}

