function createSortedArray(instructions) {
  // Compare each value with every earlier one directly.
  let total = 0;
  for (let i = 0; i < instructions.length; i++) {
    let less = 0, greater = 0;
    for (let j = 0; j < i; j++) {
      if (instructions[j] < instructions[i]) less++;
      else if (instructions[j] > instructions[i]) greater++;
    }
    total += Math.min(less, greater);
  }
  return total % 1000000007;
}

