function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 2000 : int(1, 12);
  const roll = rand();
  // Narrow ranges give many equal values; wide ranges give mostly distinct ones.
  const top = large ? (roll < 0.3 ? 50 : 100000) : (roll < 0.6 ? int(1, 8) : 100000);
  const instructions = Array.from({ length: n }, () => int(1, top));
  if (rand() < 0.15) instructions.sort((a, b) => (roll < 0.5 ? a - b : b - a));
  return [instructions];
}
